   {"id":"wb-2.6-01","type":"multi","diff":1,"skill":"element-or-compound","source":"wb","lang":"en","q":"Select all the TRUE statements.","svg":null,"choices":["Each element is made of only one type of atom.","Oxygen is a compound.","Calcium is an element.","Water is an element.","A compound is made of more than one type of atom bonded together."],"answer":[0,2,4],"accept":[],"tol":0,"unitLabel":"","hints":["Oxygen có trong bảng tuần hoàn không?","Công thức của nước H₂O có mấy loại nguyên tử?","Ô trong bảng tuần hoàn luôn là nguyên tố hay hợp chất?"],"explain":"Đúng: (1), (3), (5). Oxygen là nguyên tố (chỉ có nguyên tử O); nước H₂O có hai loại nguyên tử nên là hợp chất.","why":null},
   {"id":"wb-2.6-02","type":"mc","diff":1,"skill":"naming-compounds","source":"wb","lang":"en","q":"Which elements are in potassium chloride?","svg":null,"choices":["potassium and chlorine","potassium, chlorine and oxygen","phosphorus and chlorine","potassium and carbon"],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Phần đầu tên là kim loại nào?","Đuôi «-ide» trong chloride đến từ nguyên tố nào?","Tên có đuôi «-ate» không? Vậy có oxygen không?"],"explain":"Potassium chloride gồm potassium (kim loại) và chlorine (đổi thành chloride). Không có đuôi «-ate» nên không có oxygen.","why":null},
   {"id":"wb-2.6-03","type":"text","diff":2,"skill":"naming-compounds","source":"wb","lang":"en","q":"Suggest the name of the compound made of copper and oxygen.","svg":null,"choices":null,"answer":"copper oxide","accept":["copper(II) oxide","copper ii oxide","đồng oxit","đồng oxide","copper oxit"],"tol":0,"unitLabel":"","hints":["Kim loại nào đứng trước trong tên?","Oxygen đổi đuôi thành gì?","Ghép hai phần lại."],"explain":"Copper (kim loại) đứng trước, oxygen đổi thành oxide: copper oxide.","why":null},
   {"id":"wb-2.6-04","type":"mc","diff":2,"skill":"naming-compounds","source":"wb","lang":"en","q":"What is the name of the compound formed from calcium, carbon and oxygen?","svg":null,"choices":["calcium carbonate","calcium carbide","calcium oxide","carbon calcide"],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Kim loại nào đứng trước?","Có hai phi kim và một trong số đó là oxygen — đuôi tên sẽ là gì?","«Calcium oxide» có chứa carbon không?"],"explain":"Calcium + carbon + oxygen → calcium carbonate (đuôi «-ate» vì có thêm oxygen). Đó là thành phần chính của đá vôi.","why":null},
   {"id":"wb-2.6-05","type":"text","diff":2,"skill":"writing-formulae","source":"wb","lang":"en","q":"Write the formula for sulfur dioxide (one sulfur atom bonded to two oxygen atoms).","svg":null,"choices":null,"answer":"SO2","accept":["SO₂","O2S"],"tol":0,"unitLabel":"","hints":["Kí hiệu của sulfur và oxygen là gì?","Số 2 viết sau kí hiệu nào?","Chỉ có 1 nguyên tử sulfur — có cần viết số 1 không?"],"explain":"S cho sulfur, O cho oxygen, chỉ số 2 sau O: SO₂. Không viết số 1.","why":null},
   {"id":"wb-2.6-06","type":"mc","diff":3,"skill":"writing-formulae","source":"wb","lang":"en","q":"A student wrote the formula of sodium carbonate as NA2CO3. What is wrong?","svg":null,"choices":["The second letter of a symbol must be lower case: it should be Na₂CO₃.","The numbers should be written large, not small.","Nothing is wrong.","Carbon should be written in lower case: c."],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Kí hiệu của sodium là gì? Chữ thứ hai viết hoa hay thường?","«NA» có thể bị đọc nhầm thành hai nguyên tố nào?","Chữ đầu tiên của kí hiệu luôn viết hoa hay thường?"],"explain":"Sodium là Na, chữ thứ hai viết thường. «NA» có thể bị hiểu là N (nitrogen) và một nguyên tố «A». Đúng là Na₂CO₃, với chỉ số viết nhỏ phía dưới.","why":null},
   {"id":"wb-2.6-07","type":"num","diff":3,"skill":"reading-formulae","source":"wb","lang":"en","q":"The sugar maltose has the formula C₁₂H₂₂O₁₁. How many atoms in total are in one particle of maltose?","svg":null,"choices":null,"answer":45,"accept":[],"tol":0,"unitLabel":"","hints":["Có mấy nguyên tử carbon?","Có mấy nguyên tử hydrogen, mấy nguyên tử oxygen?","Cộng 12, 22 và 11."],"explain":"12 C + 22 H + 11 O = 45 nguyên tử.","why":null},
   {"id":"wb-2.6-08","type":"num","diff":3,"skill":"reading-formulae","source":"wb","lang":"en","q":"2C₁₂H₂₂O₁₁ means two particles of maltose. How many hydrogen atoms are there in 2C₁₂H₂₂O₁₁?","svg":null,"choices":null,"answer":44,"accept":[],"tol":0,"unitLabel":"","hints":["Một phân tử maltose có mấy nguyên tử hydrogen?","Số 2 viết to ở đầu cho biết điều gì?","Nhân số nguyên tử hydrogen trong một phân tử với số phân tử."],"explain":"Một phân tử có 22 nguyên tử H; số 2 phía trước nghĩa là hai phân tử: 2 × 22 = 44 nguyên tử hydrogen.","why":null}
